import{_ as a,o as t,c as s,a2 as i}from"./chunks/framework.doxMM-x8.js";const k=JSON.parse('{"title":"Quick Start","description":"","frontmatter":{"docLocale":"en","counterpart":"/getting-started/quickstart","contentType":"guide","prev":{"text":"Project documentation","link":"/en/docs/"},"next":{"text":"Lab and asset library","link":"/en/guides/lab-viewer"}},"headers":[],"relativePath":"en/getting-started/quickstart.md","filePath":"en/getting-started/quickstart.md"}'),n={name:"en/getting-started/quickstart.md"};function r(l,e,o,h,p,d){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;">​</a></h1><p>Goal: start the existing Lab Word application and verify HTTP and Web access. Validated Viewer evidence currently comes from a <a href="./../guides/lab-viewer">separate preview</a>; record production Lab integration acceptance separately.</p><h2 id="_1-install-and-start" tabindex="-1">1. Install And Start <a class="header-anchor" href="#_1-install-and-start" aria-label="Permalink to &quot;1. Install And Start&quot;">​</a></h2><p>Prepare Docker/Compose and the pinned versions: Rust 1.96.0, Node 24.18.0, pnpm 11.17.0 and just 1.58.0. Consult the <a href="https://github.com/CaiZongyuan/labworld/blob/e6f80f5edb69c802ca46bdb296bff2fce04c38c1/rust-toolchain.toml" target="_blank" rel="noreferrer">Rust toolchain</a>, <a href="https://github.com/CaiZongyuan/labworld/blob/e6f80f5edb69c802ca46bdb296bff2fce04c38c1/.node-version" target="_blank" rel="noreferrer">Node version</a>, <a href="https://github.com/CaiZongyuan/labworld/blob/e6f80f5edb69c802ca46bdb296bff2fce04c38c1/package.json" target="_blank" rel="noreferrer">package configuration</a> and <a href="https://github.com/CaiZongyuan/labworld/blob/e6f80f5edb69c802ca46bdb296bff2fce04c38c1/.tool-versions" target="_blank" rel="noreferrer">tool versions</a>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/CaiZongyuan/labworld.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> labworld</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frozen-lockfile</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>Run from the repository root. The first launch downloads dependencies and compiles Rust. The development script starts PostgreSQL, Redis, RustFS and Mailpit, applies migrations, initializes storage, then runs API, Worker and Web. It writes to local development volumes.</p><p>Defaults come from <a href="https://github.com/CaiZongyuan/labworld/blob/e6f80f5edb69c802ca46bdb296bff2fce04c38c1/.env.example" target="_blank" rel="noreferrer">.env.example</a>; create an untracked <code>.env</code> to override them. See the <a href="./../reference/config">generated API configuration</a>.</p><h2 id="_2-observe-the-result" tabindex="-1">2. Observe The Result <a class="header-anchor" href="#_2-observe-the-result" aria-label="Permalink to &quot;2. Observe The Result&quot;">​</a></h2><p>Keep development running and use another terminal:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:3000/health/live</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:3000/health/ready</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:3000/api/v1/system/status</span></span></code></pre></div><p>Expect HTTP 200 with <code>x-request-id</code>. Live reports the running process; ready checks dependencies and migrations; status returns the actual system state.</p><p>Open <a href="http://127.0.0.1:5173/register" target="_blank" rel="noreferrer">http://127.0.0.1:5173/register</a> to create a development account. The first account is Owner; later accounts are Members. Passwords contain 12–128 characters. Read development email at <a href="http://127.0.0.1:8025" target="_blank" rel="noreferrer">http://127.0.0.1:8025</a>. Existing platform behavior exercises authentication and business operations. Lab behavior follows its version&#39;s integration acceptance.</p><h2 id="_3-check-dependency-failure-and-recovery" tabindex="-1">3. Check Dependency Failure And Recovery <a class="header-anchor" href="#_3-check-dependency-failure-and-recovery" aria-label="Permalink to &quot;3. Check Dependency Failure And Recovery&quot;">​</a></h2><p>Only in your own development environment, stop PostgreSQL:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> db-down</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:3000/health/ready</span></span></code></pre></div><p>Ready should return 503 while live remains 200. Restore the database:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --wait</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgres</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:3000/health/ready</span></span></code></pre></div><p>Ready should return 200 again. For migration mismatches, check the source revision and run <code>just migrate</code>. API startup does not migrate automatically. After adding SQL, migrate and restart development so the embedded migration set is refreshed.</p><h2 id="stop-and-continue" tabindex="-1">Stop And Continue <a class="header-anchor" href="#stop-and-continue" aria-label="Permalink to &quot;Stop And Continue&quot;">​</a></h2><p><code>Ctrl+C</code> stops API, Worker and Web; <code>just services-down</code> stops containers while retaining volumes. For port conflicts, keep APP_BIND, VITE_API_PROXY and APP_ORIGIN consistent. Database port changes require both POSTGRES_PORT and DATABASE_URL.</p><p>Next, <a href="./../guides/lab-viewer">run the Lab Viewer preview</a> or read the <a href="./../architecture/project-structure">project structure</a>. Run documentation with <code>just docs</code> at <a href="http://127.0.0.1:5174/labworld/en/docs/" target="_blank" rel="noreferrer">http://127.0.0.1:5174/labworld/en/docs/</a>.</p><hr><p>Source version：<code>e6f80f5edb69</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/e6f80f5edb69c802ca46bdb296bff2fce04c38c1/docs/getting-started/quickstart.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,23)])])}const u=a(n,[["render",r]]);export{k as __pageData,u as default};
